Juggler Sequence is a series of integers in which the first term starts with a positive integer number n and the remaining terms are generated from the immediate previous term using the below recurrence relation: n_{k+1} =\begin{cases}\lfloor n_k^{1/2} \rfloor & \text{for even } n_k \\\lfloor n_k^{3/2} \rfloor & \text{for odd } n_k\end{cases}.Note: The terms in Juggler Sequence first increase to a peak value and then start decreasing.The last term in Juggler Sequence is always 1.Given a number n, find the Juggler Sequence for this number as the first term of the sequence until it becomes 1.Examples:Input: n = 9Output: 9 27 140 11 36 6 2 1Explanation: We start with 9 and use the above formula to get next terms.Input: n = 6Output: 6 2 1Explanation: [61/2] = 2, [21/2] = 1.Try It YourselfTable of ContentRecursive ApproachIterative ApproachRecursive ApproachThe idea is to generate the Juggler sequence starting from n using recursion. At each step, print n, and if n == 1, stop.  We compute the next term based on parity: if n is even, take √n, else take n × √n, and recursively repeat until 1 is reached.
            C++

    #include <iostream>
#include <vector>
#include <cmath>
using namespace std;

// Recursive function to generate
// the Juggler sequence
void solve(long long n, vector<long long> &res)
{
    // Store current value
    res.push_back(n);

    // Base case: stop when n becomes 1
    if (n <= 1)
        return;

    // If n is even, take floor(sqrt(n))
    else if (n % 2 == 0)
    {
        n = floor(sqrt(n));
        solve(n, res);
    }
    // If n is odd, take floor(n * sqrt(n))
    else
    {
        n = floor(n * sqrt(n));
        solve(n, res);
    }
}

// Function to return the Juggler sequence
vector<long long> jugglerSequence(long long n)
{
    vector<long long> res;

    // Call recursive helper
    solve(n, res);

    return res;
}

// Driver code
int main()
{
    long long n = 9;

    // Get the Juggler sequence
    vector<long long> res = jugglerSequence(n);

    // Print the sequence
    for (auto x : res)
        cout << x << " ";

    return 0;
}


            C

    #include <stdio.h>
#include <math.h>
#include <stdlib.h>

// Recursive function to generate
// the Juggler sequence
void solve(long long n, long long **res, int *size)
{
    // Store current value
    (*res) = realloc(*res, (*size + 1) * sizeof(long long));
    (*res)[(*size)++] = n;

    // Base case: stop when n becomes 1
    if (n <= 1)
        return;

    // If n is even, take floor(sqrt(n))
    else if (n % 2 == 0)
    {
        n = (long long)floor(sqrt(n));
        solve(n, res, size);
    }
    // If n is odd, take floor(n * sqrt(n))
    else
    {
        n = (long long)floor(n * sqrt(n));
        solve(n, res, size);
    }
}

// Function to return the Juggler sequence
long long* jugglerSequence(long long n, int *size)
{
    long long *res = (long long *)malloc(sizeof(long long));
    *size = 0;

    // Call recursive helper
    solve(n, &res, size);

    return res;
}

// Driver code
int main()
{
    long long n = 9;
    int size;

    // Get the Juggler sequence
    long long *res = jugglerSequence(n, &size);

    // Print the sequence
    for (int i = 0; i < size; i++)
        printf("%lld ", res[i]);

    free(res);
    return 0;
}


